"""Location-scale family generated by Exp(1): X = mu + sigma Z.
(a) densities for (mu,sigma) in {(0,1),(1,2),(-1,0.5)}; (b) Q_X(u) vs Q_Z(u)=-ln(1-u), u in [0.02,0.98]."""
from pathlib import Path
import sys
HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent/'dfam-common'))
from common import *

pars = [((0, 1), BLUE), ((1, 2), YELLOW), ((-1, 0.5), PURPLE)]
fig, (a, b) = figure(width_mm=108, height_mm=48, ncols=2)
x = np.linspace(-1.6, 7, 2000)
for (mu, s), c in pars:
    f = np.where(x >= mu, np.exp(-(x-mu)/s)/s, 0.0)
    a.plot(x, f, color=c, lw=1.4)
a.text(-0.55, 1.75, r'$(-1,0.5)$', color=PURPLE, fontsize=7.5)
a.text(0.25, 0.88, r'$(0,1)$', color=BLUE, fontsize=7.5)
a.text(2.2, 0.36, r'$(1,2)$', color=YELLOW, fontsize=7.5)
a.set_xlim(-1.6, 7); a.set_ylim(0, 2.1); a.set_xlabel('$x$', labelpad=1); a.set_ylabel('$f_X(x)$')
u = np.linspace(0.02, 0.98, 200); qz = -np.log(1-u)
for (mu, s), c in pars:
    b.plot(qz, mu+s*qz, color=c, lw=1.4)
med = (np.log(2), 1+2*np.log(2))
b.scatter([med[0]], [med[1]], s=16, color=RED, zorder=4)
b.text(0.1, 3.9, r'$(\ln 2,\,1+2\ln 2)$', fontsize=7.5, va='bottom')
b.text(2.9, 8.0, r'$\sigma=2$', color=YELLOW, fontsize=7.5, ha='right')
b.text(3.95, 4.3, r'$\sigma=1$', color=BLUE, fontsize=7.5, ha='right')
b.text(3.95, 1.55, r'$\sigma=0.5$', color=PURPLE, fontsize=7.5, ha='right')
b.set_xlim(0, 4.1); b.set_xlabel(r'$Q_Z(u)$', labelpad=1); b.set_ylabel(r'$Q_X(u)$')
tag(a, '(a)', y=-0.27); tag(b, '(b)', y=-0.27)
save(fig, HERE, 'figure', {'base': 'Exp(1)', 'params': [[0, 1], [1, 2], [-1, 0.5]], 'median_12': float(med[1]),
     'quartiles_12': [float(1-2*np.log(0.75)), float(1+2*np.log(4))], 'iqr_12': float(2*np.log(3))})
